package com.oms.inventory;
import com.oms.inventory.service.impl.*;
import org.junit.jupiter.api.*;
import java.util.*;
import java.util.concurrent.*;
import static org.junit.jupiter.api.Assertions.*;

class OrderFulfillmentAdjustmentTest {
    OrderVirtualOutboundTest f=new OrderVirtualOutboundTest();OrderFulfillmentAdjustmentService service;
    @BeforeAll static void start(){OrderStockTest.start();}
    @AfterAll static void stop(){OrderStockTest.stop();}
    @BeforeEach void seed(){f.seed();service=OrderStockTest.context.getBean(OrderFulfillmentAdjustmentService.class);}
    long n(String sql){return OrderStockTest.db.queryForObject(sql,Long.class);}
    Map<String,Object> command(String mode,List<Map<String,Object>> receipts,boolean finish){List<Map<String,Object>> rows=new ArrayList<>();for(Map<String,Object> r:receipts){long qty=((Number)r.get("quantity")).longValue()-((Number)r.get("outbound_quantity")).longValue();if(qty>0)rows.add(f.row("allocation_id",r.get("id"),"quantity",qty,"outbound_before",r.get("outbound_quantity"),"sku_sn",r.get("sku_sn"),"stock_source_id",r.get("stock_source_id")));}return f.row("request_id","CF"+UUID.randomUUID().toString().replace("-",""),"mode",mode,"channel_id",1,"platform_tid","12345","allocations",rows,"finish_order",finish);}
    @Test void replanKeepsLogicalReservationAndNewAllocationDoesNotDoubleLock(){Map<String,Object> c=command("REPLAN",f.allocate(10,false),false);service.apply("VERIFY",c);service.apply("VERIFY",c);assertEquals(10,n("SELECT reserved_stock FROM oms_inventory"));assertEquals(0,n("SELECT zp_lock_number FROM wms_inventory"));assertEquals(100,n("SELECT zp_available_number FROM wms_inventory"));assertEquals(10,n("SELECT released_quantity FROM oms_order_warehouse_allocation"));f.fixture.allocate("12345",false,false,false,"W1");assertEquals(10,n("SELECT SUM(quantity-released_quantity) FROM oms_order_warehouse_allocation"));assertEquals(10,n("SELECT zp_lock_number FROM wms_inventory"));assertEquals(10,n("SELECT reserved_stock FROM oms_inventory"));}
    @Test void terminateRemainderAfterOutboundPreservesPhysicalDeductionAndConsumedSources(){List<Map<String,Object>> a=f.allocate(10,false);f.service.outbound("VERIFY",f.command("VIRTUAL_CUTOFF_1",a,4));Map<String,Object> c=command("TERMINATE",f.receipts(),true);service.apply("VERIFY",c);service.apply("VERIFY",c);assertEquals(96,n("SELECT total_stock FROM oms_inventory"));assertEquals(96,n("SELECT zp_actual_number FROM wms_inventory"));assertEquals(0,n("SELECT reserved_stock FROM oms_inventory"));assertEquals(0,n("SELECT zp_lock_number FROM wms_inventory"));assertEquals(4,n("SELECT reserved_quantity FROM oms_order_stock_demand"));assertEquals(4,n("SELECT outbound_quantity FROM oms_order_stock_demand"));assertEquals(6,n("SELECT cancelled_quantity FROM oms_order_stock_demand"));assertEquals(4,n("SELECT quantity FROM oms_order_stock_source"));assertEquals(6,n("SELECT released_quantity FROM oms_order_stock_source"));assertEquals(0,n("SELECT pending_stock FROM oms_channel_inventory"));}
    @Test void lockSourceReturnsToOriginalChannelRatherThanPublicStock(){Map<String,Object> c=command("TERMINATE",f.allocate(20,true),true);service.apply("VERIFY",c);assertEquals(100,n("SELECT total_stock FROM oms_inventory"));assertEquals(0,n("SELECT reserved_stock FROM oms_inventory"));assertEquals(30,n("SELECT allocated_stock FROM oms_inventory"));assertEquals(70,n("SELECT available_stock FROM oms_inventory"));assertEquals(30,n("SELECT zp_lock_number FROM wms_inventory"));assertEquals(0,n("SELECT occupied_quantity FROM rule_stock_reservation"));assertEquals(30,n("SELECT allocated_stock FROM oms_channel_inventory"));}
    @Test void mixedSourcesReleaseExactlyOnce(){service.apply("VERIFY",command("TERMINATE",f.allocate(40,true),true));assertEquals(0,n("SELECT reserved_stock FROM oms_inventory"));assertEquals(70,n("SELECT available_stock FROM oms_inventory"));assertEquals(30,n("SELECT allocated_stock FROM oms_inventory"));assertEquals(70,n("SELECT zp_available_number FROM wms_inventory"));assertEquals(40,n("SELECT cancelled_quantity FROM oms_order_stock_demand"));}
    @SuppressWarnings("unchecked") @Test void staleOutboundAndWrongIdentityRollbackEveryRelease(){List<Map<String,Object>> a=f.allocate(40,true);Map<String,Object> c=command("TERMINATE",a,false);List<Map<String,Object>> rows=(List<Map<String,Object>>)c.get("allocations");rows.get(1).put("outbound_before",1);assertThrows(IllegalArgumentException.class,()->service.apply("VERIFY",c));assertEquals(40,n("SELECT reserved_stock FROM oms_inventory"));assertEquals(0,n("SELECT SUM(released_quantity) FROM oms_order_warehouse_allocation"));assertEquals(30,n("SELECT occupied_quantity FROM rule_stock_reservation"));assertEquals(0,n("SELECT COUNT(*) FROM oms_order_fulfillment_adjustment"));}
    @Test void crossCompanyAndChangedReplayAreRejected(){Map<String,Object> c=command("REPLAN",f.allocate(10,false),false);assertThrows(IllegalArgumentException.class,()->service.apply("OTHER",c));service.apply("VERIFY",c);c.put("mode","TERMINATE");assertThrows(IllegalArgumentException.class,()->service.apply("VERIFY",c));assertEquals(10,n("SELECT reserved_stock FROM oms_inventory"));}
    @Test void terminationCannotCloseStillOccupiedDemand(){f.allocate(10,false);assertThrows(IllegalArgumentException.class,()->service.apply("VERIFY",command("TERMINATE",Collections.emptyList(),true)));assertEquals(10,n("SELECT reserved_stock FROM oms_inventory"));}
    @Test void exchangeReductionRequiresWithdrawalAndOnlyReleasesItsQuantity(){List<Map<String,Object>> allocated=f.allocate(10,false);Map<String,Object> reduce=command("REDUCE",Collections.emptyList(),false);reduce.put("demands",Collections.singletonList(f.row("platform_oid",OrderStockTest.db.queryForObject("SELECT platform_oid FROM oms_order_stock_demand",String.class),"quantity",3)));assertThrows(IllegalArgumentException.class,()->service.apply("VERIFY",reduce));service.apply("VERIFY",command("REPLAN",allocated,false));service.apply("VERIFY",reduce);service.apply("VERIFY",reduce);assertEquals(3,n("SELECT cancelled_quantity FROM oms_order_stock_demand"));assertEquals(7,n("SELECT reserved_quantity FROM oms_order_stock_demand"));assertEquals(7,n("SELECT reserved_stock FROM oms_inventory"));assertEquals(100,n("SELECT zp_actual_number FROM wms_inventory"));assertEquals(0,n("SELECT zp_lock_number FROM wms_inventory"));}
    @Test void replanAfterPartialOutboundKeepsConsumedPartAndCanAllocateOnlyRemainder(){List<Map<String,Object>> a=f.allocate(10,false);f.service.outbound("VERIFY",f.command("VIRTUAL_CUTOFF_2",a,4));service.apply("VERIFY",command("REPLAN",f.receipts(),false));assertEquals(6,n("SELECT reserved_stock FROM oms_inventory"));assertEquals(4,n("SELECT quantity-released_quantity FROM oms_order_warehouse_allocation"));f.fixture.allocate("12345",false,true,false,"W1");assertEquals(10,n("SELECT SUM(quantity-released_quantity) FROM oms_order_warehouse_allocation"));assertEquals(6,n("SELECT zp_lock_number FROM wms_inventory"));}
    @Test void concurrentCancelAndOutboundHaveOnlyOneWinner() throws Exception {List<Map<String,Object>> a=f.allocate(10,false);Map<String,Object> c=command("TERMINATE",a,true),out=f.command("VIRTUAL_CUTOFF_RACE",a,10);ExecutorService pool=Executors.newFixedThreadPool(2);try{Future<Boolean> one=pool.submit(()->{try{service.apply("VERIFY",c);return true;}catch(IllegalArgumentException e){return false;}}),two=pool.submit(()->{try{f.service.outbound("VERIFY",out);return true;}catch(IllegalArgumentException e){return false;}});assertNotEquals(one.get(15,TimeUnit.SECONDS),two.get(15,TimeUnit.SECONDS));assertEquals(0,n("SELECT reserved_stock FROM oms_inventory"));assertTrue(n("SELECT zp_lock_number FROM wms_inventory")>=0);assertEquals(n("SELECT total_stock FROM oms_inventory"),n("SELECT zp_actual_number FROM wms_inventory"));}finally{pool.shutdownNow();}}
}
